export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"vi","term":"Bitcoin (BTC)","aka":["BTC","Bitcoin"],"short":"Bitcoin (BTC) là đồng tiền mã hóa đầu tiên, ra đời năm 2009, chạy trên blockchain riêng dùng cơ chế bằng chứng công việc và có tổng cung tối đa cố định 21 triệu đồng.","body":[["Bitcoin do một người hoặc nhóm ẩn danh lấy tên ",["Satoshi","satoshi"]," Nakamoto tạo ra. ",["Mạng lưới","blockchain-network"]," không có công ty điều hành; các thợ đào cạnh tranh để thêm khối mới khoảng 10 phút một lần và nhận phần thưởng khối cùng phí giao dịch."],"Nguồn cung được lập trình sẵn: tối đa 21 triệu BTC, và phần thưởng khối giảm một nửa khoảng mỗi 4 năm (halving). Sau đợt halving tháng 4 năm 2024, phần thưởng còn 3,125 BTC mỗi khối. Mỗi BTC chia được thành 100.000.000 satoshi, nên bạn không cần mua nguyên một đồng.",["Nhiều người xem Bitcoin như tài sản lưu trữ giá trị dài hạn, nhưng giá BTC vẫn ",["biến động","volatility"]," mạnh. Từ tháng 1 năm 2024, các ",["quỹ ETF Bitcoin","spot-bitcoin-etf"]," giao ngay đã được giao dịch tại Mỹ. Trên sàn, BTC thường là cặp có ",["thanh khoản","liquidity"]," cao nhất cả ở ",["thị trường spot","spot-trading"]," lẫn hợp đồng tương lai vĩnh cửu."]],"example":"Giả sử BTC đang ở mức 50.000 USDT và bạn muốn mua 100 USDT. Bạn sẽ nhận 100 / 50.000 = 0,002 BTC, tức 200.000 satoshi (chưa trừ phí giao dịch). Nếu giá sau đó giảm 20% xuống 40.000 USDT, phần BTC của bạn còn trị giá 80 USDT; nếu tăng 20% lên 60.000 USDT, nó trị giá 120 USDT. Số BTC bạn giữ không đổi, chỉ giá trị quy đổi thay đổi.","mistakes":["Nghĩ rằng phải có đủ tiền mua 1 BTC mới bắt đầu được.","Gửi BTC qua sai mạng, ví dụ chọn mạng BEP20 trong khi địa chỉ nhận chỉ hỗ trợ mạng Bitcoin gốc.","Dùng đòn bẩy cao với BTC vì tin rằng nó ít biến động hơn altcoin."],"faq":[{"q":"Có bao nhiêu Bitcoin tồn tại?","a":"Tổng cung tối đa là 21 triệu BTC theo giao thức. Phần lớn đã được đào, phần còn lại được phát hành dần qua phần thưởng khối giảm theo mỗi kỳ halving."},{"q":"Ai kiểm soát Bitcoin?","a":"Không có công ty hay chính phủ nào điều hành Bitcoin. Quy tắc mạng được duy trì bởi các node, thợ đào và nhà phát triển, và muốn thay đổi thì cần sự đồng thuận rộng rãi."}],"title":"Bitcoin (BTC) là gì? Cách hoạt động và nguồn cung","description":"Bitcoin là gì, vì sao chỉ có 21 triệu BTC, halving là gì và cách mua một phần nhỏ BTC tính bằng satoshi.","related":[["satoshi","Satoshi (sats)","Satoshi (sats) là đơn vị nhỏ nhất của Bitcoin, với 1 BTC bằng 100.000.000 satoshi, giúp bạn mua và chuyển những phần rất nhỏ của một đồng BTC."],["bitcoin-halving","Bitcoin halving (sự kiện giảm một nửa)","Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới."],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng."],["spot-bitcoin-etf","ETF Bitcoin giao ngay (spot Bitcoin ETF)","ETF Bitcoin giao ngay là quỹ hoán đổi danh mục niêm yết trên sàn chứng khoán, nắm giữ BTC thật và cho nhà đầu tư tiếp xúc với giá Bitcoin qua tài khoản chứng khoán."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Một bitcoin đắt như vậy. Tôi vẫn có thể mua một phần chứ?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"vi","term":"Bằng chứng công việc (Proof of Work - PoW)","aka":["PoW","proof of work","bằng chứng công việc"],"short":"Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng.","body":[["Thợ đào liên tục thử các con số (nonce) để tạo ra mã băm của khối nhỏ hơn một mục tiêu do mạng đặt ra. Việc này tốn điện và máy móc, nhưng kiểm tra kết quả thì rất nhanh. ",["Bitcoin","bitcoin"]," là mạng PoW lớn nhất, ngoài ra còn có Litecoin, Dogecoin và một số mạng khác."],"Độ khó được tự động điều chỉnh để thời gian tạo khối ổn định. Với Bitcoin, độ khó thay đổi sau mỗi 2.016 khối, khoảng 2 tuần, nhằm giữ nhịp trung bình 10 phút một khối dù có thêm hay bớt máy đào.","PoW bảo vệ mạng bằng chi phí thật: muốn viết lại lịch sử, kẻ tấn công cần kiểm soát phần lớn tổng sức đào (tấn công 51%), điều rất tốn kém trên mạng lớn nhưng dễ hơn trên mạng nhỏ. Điểm bị phê bình nhiều nhất là mức tiêu thụ điện năng."],"example":"Giả sử tổng sức đào của một mạng là 500 EH/s và bạn vận hành máy đào với 0,5 EH/s, tức 0,1% mạng. Mạng tạo 144 khối mỗi ngày, nên trung bình bạn có cơ hội tìm được khoảng 0,144 khối mỗi ngày, hay khoảng 1 khối mỗi 7 ngày. Vì đây là xác suất, có tuần bạn tìm được 2 khối, có tuần không tìm được khối nào, nên thợ đào nhỏ thường tham gia pool đào để thu nhập đều hơn.","mistakes":["Nghĩ rằng ai đào nhiều coin thì kiểm soát được mạng, trong khi quy tắc vẫn do các node kiểm tra.","Cho rằng mạng PoW nhỏ an toàn như Bitcoin, dù tấn công 51% trên mạng nhỏ rẻ hơn nhiều.","Nhầm PoW với staking và tin rằng có thể đào Bitcoin bằng điện thoại."],"faq":[{"q":"PoW khác PoS thế nào?","a":"PoW dùng sức mạnh tính toán và điện năng để bảo vệ mạng, còn PoS dùng tài sản được khóa (stake) của validator. PoS tiêu tốn ít điện hơn nhiều."},{"q":"Tấn công 51% là gì?","a":"Đó là khi một bên kiểm soát hơn một nửa sức đào và có thể sắp xếp lại các khối gần đây, ví dụ để chi tiêu hai lần. Trên mạng lớn, chi phí làm việc này cực kỳ cao."}],"title":"Proof of Work (PoW) là gì? Bằng chứng công việc","description":"Proof of Work là gì, thợ đào tạo khối thế nào, độ khó điều chỉnh ra sao và vì sao PoW được coi là an toàn.","related":[["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng."],["hash-rate","Hash rate (tốc độ băm)","Hash rate là tổng sức mạnh tính toán mà các máy đào dùng để bảo vệ một blockchain proof of work, đo bằng số phép băm mỗi giây."],["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."],["bitcoin-halving","Bitcoin halving (sự kiện giảm một nửa)","Bitcoin halving là sự kiện được lập trình sẵn, cứ mỗi 210.000 khối (khoảng 4 năm) thì phần thưởng khối cho thợ đào giảm đi một nửa, làm chậm tốc độ phát hành BTC mới."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"vi","term":"Mở khóa token (Token unlock)","aka":["token unlock","mở khóa token","vesting"],"short":"Mở khóa token (token unlock) là thời điểm một lượng token trước đây bị khóa theo lịch vesting được phép chuyển và bán, thường là phần của đội ngũ, nhà đầu tư hoặc quỹ dự án.","body":["Khi dự án ra mắt, phần lớn token thường bị khóa để tránh người trong cuộc bán ngay. Lịch vesting quy định thời gian khóa ban đầu (cliff) và tốc độ mở dần sau đó, ví dụ khóa 12 tháng rồi mở đều hàng tháng trong 2 năm.",["Mở khóa làm tăng nguồn cung có thể bán. Không phải ai nhận token cũng bán ngay, nhưng các đợt mở khóa lớn so với ",["nguồn cung lưu hành","circulating-supply"]," thường được thị trường theo dõi sát vì có thể tạo áp lực giá trước và sau sự kiện."],["Hãy xem ba yếu tố: lượng mở khóa so với lưu hành hiện tại, ai nhận (đội ngũ, nhà đầu tư sớm có giá vốn thấp hay quỹ hệ sinh thái), và ",["khối lượng giao dịch","trading-volume"]," hàng ngày có hấp thụ nổi không. Lịch có thể thay đổi nếu dự án công bố điều chỉnh."]],"example":["Một token đang lưu hành 300 triệu, giá 0,8 ",["USDT","usdt"],", khối lượng giao dịch trung bình 6 triệu USDT mỗi ngày. Tuần sau có đợt mở khóa 45 triệu token cho nhà đầu tư sớm, tức 15% nguồn cung lưu hành, trị giá 36 triệu USDT ở giá hiện tại. Nếu chỉ một phần ba lượng này được bán, đó là 12 triệu USDT, bằng gấp đôi khối lượng một ngày bình thường."],"mistakes":["Mua token ngay trước đợt mở khóa lớn mà không biết lịch.","Chỉ nhìn số token mở khóa mà không so với nguồn cung lưu hành và khối lượng giao dịch.","Nghĩ rằng mọi đợt mở khóa đều khiến giá giảm."],"faq":[{"q":"Token unlock có làm giá giảm không?","a":"Không phải lúc nào cũng vậy. Ảnh hưởng tùy vào quy mô mở khóa, ai nhận token và nhu cầu thị trường lúc đó."},{"q":"Cliff trong vesting là gì?","a":"Cliff là khoảng thời gian đầu mà token hoàn toàn bị khóa. Sau cliff, token bắt đầu được mở theo lịch, có thể một lần hoặc chia đều theo tháng."}],"title":"Token unlock là gì? Lịch mở khóa token","description":"Token unlock là gì, vesting và cliff hoạt động thế nào, vì sao đợt mở khóa lớn có thể tạo áp lực bán lên giá token.","related":[["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."],["circulating-supply","Nguồn cung lưu hành (Circulating supply)","Nguồn cung lưu hành (circulating supply) là số lượng coin hoặc token đang thực sự có trên thị trường và có thể giao dịch, không tính phần bị khóa, chưa phát hành hoặc đã bị đốt."],["fully-diluted-valuation","Định giá pha loãng hoàn toàn (FDV)","Định giá pha loãng hoàn toàn (FDV) là giá hiện tại của token nhân với tổng cung tối đa, cho biết dự án sẽ được định giá bao nhiêu nếu toàn bộ token đã được phát hành."],["airdrop","Airdrop","Airdrop là việc một dự án phát token miễn phí vào ví của người dùng đủ điều kiện, thường để thưởng người dùng sớm, phân phối token rộng hơn hoặc quảng bá dự án."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"vi","term":"Lệnh giới hạn (Limit order)","aka":["lệnh limit","limit order","lệnh giới hạn"],"short":"Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh.","body":[["Với lệnh mua giới hạn, bạn đặt giá tối đa chấp nhận trả; với lệnh bán giới hạn, bạn đặt giá tối thiểu chấp nhận nhận. Nếu giá hiện tại đã tốt hơn mức bạn đặt, lệnh khớp ngay như taker. Nếu chưa, lệnh nằm trong ",["sổ lệnh","order-book"]," và khi được khớp, bạn thường hưởng ",["phí maker","maker-taker-fees"]," thấp hơn."],["Ưu điểm: kiểm soát giá và tránh ",["trượt giá","slippage"],". Nhược điểm: lệnh có thể không khớp, hoặc chỉ khớp một phần, nếu giá không chạm hoặc không đủ đối ứng. Bạn có thể bỏ lỡ cơ hội nếu giá chạy ngay trước mức đặt."],["Lệnh giới hạn thường đi kèm thiết lập thời hạn hiệu lực như ",["GTC","time-in-force"]," (giữ đến khi hủy), IOC hay FOK, và tùy chọn ",["post-only","post-only-order"]," để đảm bảo chỉ làm maker. Tên gọi và tùy chọn khác nhau đôi chút giữa các sàn."]],"example":[["ETH","ethereum"]," đang giao dịch ở 2.100 USDT. Bạn đặt lệnh mua giới hạn 1 ETH ở 2.000 USDT. Hai ngày sau giá giảm về 1.995, lệnh của bạn khớp ở 2.000 USDT, phí maker 0,02% là 0,4 USDT. So với mua ngay bằng lệnh thị trường ở 2.100 với phí taker 0,05% (1,05 USDT), bạn tiết kiệm được 100,65 USDT. Nhưng nếu giá chỉ giảm về 2.010 rồi tăng lên 2.300, lệnh không bao giờ khớp."],"mistakes":["Đặt lệnh mua giới hạn cao hơn giá hiện tại và bị khớp ngay như lệnh thị trường.","Quên lệnh giới hạn cũ vẫn đang mở rồi bị khớp ngoài ý muốn nhiều ngày sau.","Đặt giá quá xa thị trường chỉ để chờ giá lý tưởng mà không có kế hoạch nếu lệnh không khớp."],"faq":[{"q":"Lệnh giới hạn có chắc chắn khớp không?","a":"Không. Lệnh chỉ khớp khi có đối ứng ở mức giá bạn đặt hoặc tốt hơn. Nó có thể khớp một phần hoặc không khớp."},{"q":"Lệnh giới hạn có rẻ phí hơn lệnh thị trường không?","a":"Thường là có nếu lệnh nằm chờ trong sổ lệnh và được khớp như maker. Mức phí cụ thể tùy sàn và cấp tài khoản."}],"title":"Lệnh giới hạn (limit order) là gì?","description":"Lệnh giới hạn là gì, khác lệnh thị trường ra sao, vì sao thường được phí maker và rủi ro lệnh không khớp.","related":[["market-order","Lệnh thị trường (Market order)","Lệnh thị trường (market order) là lệnh mua hoặc bán ngay lập tức ở giá tốt nhất hiện có trong sổ lệnh, ưu tiên tốc độ khớp thay vì kiểm soát giá."],["post-only-order","Lệnh chỉ đặt (Post-only)","Lệnh post-only là lệnh giới hạn chỉ được chấp nhận nếu nó nằm chờ trong sổ lệnh làm maker; nếu lệnh sẽ khớp ngay và trở thành taker, sàn tự động hủy hoặc điều chỉnh nó."],["time-in-force","Hiệu lực lệnh (Time in force: GTC, IOC, FOK)","Time in force (hiệu lực lệnh) là thiết lập quy định một lệnh giới hạn tồn tại bao lâu và xử lý thế nào nếu không khớp ngay, phổ biến nhất là GTC, IOC và FOK."],["order-book","Sổ lệnh (Order book)","Sổ lệnh (order book) là danh sách theo thời gian thực của tất cả lệnh mua và lệnh bán đang chờ khớp cho một cặp giao dịch, sắp xếp theo mức giá và khối lượng."],["maker-taker-fees","Phí maker và phí taker (Maker/Taker fee)","Phí maker và phí taker là hai mức phí giao dịch khác nhau: maker trả phí khi lệnh của bạn nằm chờ trên sổ lệnh và tạo thêm thanh khoản, taker trả phí khi lệnh của bạn khớp ngay với lệnh có sẵn."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"vi","term":"Quỹ bảo hiểm (Insurance fund)","aka":["insurance fund","quỹ bảo hiểm sàn","quỹ rủi ro"],"short":"Quỹ bảo hiểm là khoản dự trữ của sàn dùng để bù phần lỗ khi một vị thế bị thanh lý ở giá tệ hơn giá phá sản, nhằm tránh chuyển khoản lỗ đó sang người giao dịch khác.","body":[["Khi một vị thế ",["bị thanh lý","liquidation"],", sàn cố đóng nó trên thị trường. Nếu đóng được ở giá tốt hơn giá phá sản, phần ký quỹ còn dư thường được đưa vào quỹ bảo hiểm. Nếu đóng ở giá tệ hơn, quỹ bảo hiểm chi ra để bù phần thiếu."],["Quỹ lớn giúp sàn hấp thụ các cú sập mạnh mà không phải dùng ",["giảm đòn bẩy tự động (ADL)","auto-deleveraging"],". Nhiều sàn công bố số dư quỹ bảo hiểm theo từng loại hợp đồng hoặc tài sản ký quỹ, để người dùng tự theo dõi."],["Quỹ bảo hiểm khác với ",["bằng chứng dự trữ","proof-of-reserves"]," hay quỹ bảo vệ người dùng của sàn. Nó chỉ phục vụ hệ thống thanh lý phái sinh, không bảo hiểm cho tiền gửi nếu sàn bị hack hay phá sản."]],"example":["Giả sử một ",["vị thế long","long-and-short"]," ",["BTC","bitcoin"]," có giá phá sản 58.000 ",["USDT","usdt"],", nghĩa là tại đó ký quỹ về 0. Thị trường giảm nhanh và hệ thống chỉ đóng được 2 BTC ở trung bình 57.700 USDT. Phần thiếu là 2 × 300 = 600 USDT, được quỹ bảo hiểm chi trả. Ngược lại, nếu đóng được ở 58.200 USDT, phần dư 400 USDT được chuyển vào quỹ."],"mistakes":["Nghĩ rằng quỹ bảo hiểm bảo vệ số dư của bạn khi sàn gặp sự cố.","Không biết rằng phí thanh lý của bạn có thể góp vào quỹ này.","Bỏ qua quy mô quỹ khi giao dịch hợp đồng altcoin nhỏ trên sàn ít thanh khoản."],"faq":[{"q":"Quỹ bảo hiểm của sàn dùng để làm gì?","a":"Để bù lỗ khi vị thế bị thanh lý ở giá tệ hơn giá phá sản. Nhờ đó, người giao dịch đang lãi không phải gánh khoản lỗ này."},{"q":"Quỹ bảo hiểm cạn thì sao?","a":"Sàn có thể dùng cơ chế giảm đòn bẩy tự động (ADL), đóng bớt vị thế đang lãi ở phía đối diện."}],"title":"Quỹ bảo hiểm (insurance fund) của sàn là gì?","description":"Quỹ bảo hiểm sàn là gì, cách nó bù lỗ thanh lý ở giá phá sản và vì sao nó không bảo vệ tiền gửi của bạn.","related":[["auto-deleveraging","Giảm đòn bẩy tự động (ADL)","Giảm đòn bẩy tự động (ADL) là cơ chế cuối cùng của sàn: khi quỹ bảo hiểm không đủ bù lỗ từ một vị thế bị thanh lý, sàn tự đóng một phần vị thế đang lãi ở phía đối diện."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"vi","term":"Số xác nhận khối (Block confirmations)","aka":["confirmations","xác nhận","số block xác nhận"],"short":"Số xác nhận khối là số khối đã được thêm vào blockchain kể từ khối chứa giao dịch của bạn; càng nhiều xác nhận thì giao dịch càng khó bị đảo ngược.","body":["Khi giao dịch được đưa vào một khối, nó có 1 xác nhận. Mỗi khối mới nối thêm phía sau tăng thêm 1. Việc viết lại lịch sử sau nhiều khối đòi hỏi chi phí cực lớn, nên số xác nhận là thước đo độ chắc chắn.",["Sàn tự đặt số xác nhận tối thiểu trước khi ghi có khoản nạp, và con số này khác nhau theo từng coin và từng sàn. ",["Bitcoin","bitcoin"]," có khối khoảng 10 phút một lần, nên vài xác nhận có thể mất 20 đến 60 phút. Các mạng nhanh như Tron hay Solana có khối chỉ vài giây nhưng sàn có thể yêu cầu hàng chục xác nhận."],"Một số sàn ghi có số dư trước nhưng chỉ cho rút khi đủ thêm xác nhận. Trang nạp thường ghi rõ hai con số này."],"example":["Giả sử bạn nạp 0,1 BTC và sàn yêu cầu 2 xác nhận để ghi có, 6 xác nhận để mở khóa rút. Thời gian khối trung bình khoảng 10 phút, nên bạn có thể thấy số dư sau khoảng 20 phút và rút được sau khoảng 60 phút. Nếu mạng bận và giao dịch chờ trong ",["mempool","mempool"]," thêm 30 phút, mọi mốc đều lùi lại tương ứng."],"mistakes":["Hoảng sợ và gửi khiếu nại khi giao dịch mới có 1 xác nhận trong khi sàn yêu cầu nhiều hơn.","Nghĩ rằng mọi sàn yêu cầu cùng số xác nhận cho cùng một coin.","Chấp nhận giao dịch giá trị lớn với 0 xác nhận khi bán hàng qua P2P."],"faq":[{"q":"Bao nhiêu xác nhận là đủ an toàn?","a":"Tùy blockchain và giá trị giao dịch. Với Bitcoin, 6 xác nhận là mốc truyền thống cho số tiền lớn; sàn thường công bố mức riêng cho từng coin."},{"q":"Vì sao giao dịch của tôi mãi ở 0 xác nhận?","a":"Giao dịch còn nằm trong mempool, thường do phí thấp khi mạng đông. Bạn có thể chờ hoặc dùng tính năng tăng phí nếu ví hỗ trợ."}],"title":"Số xác nhận khối là gì? Vì sao nạp tiền phải chờ","description":"Số xác nhận khối (block confirmations) là gì, vì sao sàn bắt chờ khi nạp crypto và cách ước tính thời gian nạp.","related":[["transaction-hash","Mã giao dịch (Transaction hash, TxID)","Mã giao dịch (TxID hay TxHash) là chuỗi ký tự duy nhất định danh một giao dịch trên blockchain, dùng để tra cứu trạng thái, số tiền, phí và số xác nhận của giao dịch đó."],["block-explorer","Block explorer (trình khám phá khối)","Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó."],["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Báo đã gửi nhưng tiền chưa tới. Cần kiểm tra ở đâu?"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"vi","term":"Tổn thất tạm thời (Impermanent loss)","aka":["impermanent loss","IL","lỗ tạm thời"],"short":"Tổn thất tạm thời là phần giá trị bạn bị thiệt khi cung cấp thanh khoản cho pool so với việc chỉ giữ nguyên hai token, phát sinh khi giá của chúng thay đổi lệch nhau.","body":[["Khi giá một token trong pool tăng, các nhà ",["arbitrage","arbitrage"]," mua token đó ra khỏi pool cho đến khi giá cân bằng. Kết quả là bạn còn ít token tăng giá hơn và nhiều token giảm giá hơn so với lúc gửi. Giá càng lệch xa, tổn thất càng lớn, bất kể giá tăng hay giảm."],"Gọi là “tạm thời” vì nếu giá quay về đúng tỷ lệ lúc gửi, tổn thất biến mất. Nhưng nếu bạn rút khi giá đã lệch, khoản thiệt trở thành thật. Với pool 50/50, giá lệch gấp 2 lần cho tổn thất khoảng 5,7%, lệch gấp 4 lần khoảng 20%.",["Phí giao dịch và thưởng có thể bù đắp tổn thất. Pool ",["stablecoin","stablecoin"]," với stablecoin có tổn thất rất nhỏ nếu không có đồng nào ",["mất neo","depeg"],", còn ",["thanh khoản","liquidity"]," tập trung có thể khuếch đại cả phí lẫn tổn thất."]],"example":["Giả sử ",["ETH","ethereum"]," giá 2.000 ",["USDC","usdc"],", bạn gửi 1 ETH và 2.000 USDC, tổng 4.000 USDC. ETH tăng lên 4.000 USDC. Pool giờ cho bạn khoảng 0,7071 ETH và 2.828 USDC, tổng khoảng 5.657 USDC. Nếu chỉ giữ, bạn có 1 ETH cộng 2.000 USDC, tức 6.000 USDC. Tổn thất tạm thời khoảng 343 USDC, tương đương 5,7%, trước khi cộng phí giao dịch đã thu."],"mistakes":["Nghĩ rằng tổn thất tạm thời chỉ xảy ra khi giá giảm.","So lợi nhuận LP với số tiền bỏ vào ban đầu thay vì với việc chỉ nắm giữ hai token.","Gửi token biến động mạnh vào pool chỉ vì APR cao mà không ước tính tổn thất."],"faq":[{"q":"Tổn thất tạm thời có tránh được không?","a":"Không tránh hoàn toàn được với pool hai token biến động. Bạn có thể giảm bằng cách chọn cặp có giá đi cùng nhau như stablecoin với stablecoin."},{"q":"Khi nào tổn thất tạm thời thành lỗ thật?","a":"Khi bạn rút thanh khoản lúc giá đã lệch so với thời điểm gửi. Lúc đó phần chênh lệch được chốt lại."}],"title":"Impermanent loss là gì? Tổn thất tạm thời khi góp LP","description":"Tổn thất tạm thời (impermanent loss) là gì, vì sao xảy ra khi góp thanh khoản, cách tính bằng ví dụ và cách giảm rủi ro.","related":[["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."],["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống."],["yield-farming","Yield farming (Canh tác lợi suất)","Yield farming là chiến lược đưa crypto vào các giao thức DeFi như pool thanh khoản hoặc nền tảng cho vay để nhận phí, lãi và token thưởng, thường di chuyển vốn tới nơi trả lợi suất cao."],["apr-vs-apy","APR và APY","APR là lãi suất năm chưa tính lãi kép, còn APY là lợi suất năm đã tính lãi kép; cùng một mức lãi, APY luôn bằng hoặc cao hơn APR nếu lãi được cộng dồn."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"vi","term":"Staking thanh khoản (Liquid staking)","aka":["liquid staking","LST","liquid staking token"],"short":"Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake.","body":[[["Staking","staking"]," thông thường khóa coin và có thời gian chờ rút. Với liquid staking, giao thức như Lido hay Rocket Pool nhận ",["ETH","ethereum"]," của bạn, giao cho các ",["validator","validator"],", rồi phát cho bạn token stake ",["thanh khoản","liquidity"]," (LST). Giá trị LST tăng dần theo phần thưởng, qua việc số dư tự tăng hoặc tỷ giá quy đổi tăng."],["Lợi ích là vốn không bị “đóng băng”: bạn có thể bán LST trên ",["DEX","dex"],", dùng làm tài sản thế chấp để vay, hoặc góp thanh khoản. Nhiều ",["sàn tập trung","centralized-exchange"]," cũng phát hành token stake thanh khoản riêng."],"Rủi ro gồm lỗi hợp đồng, rủi ro tập trung validator, slashing, và LST mất neo, tức giao dịch thấp hơn giá trị coin gốc khi thị trường hoảng loạn. Nếu bạn đang vay bằng LST làm thế chấp, mất neo có thể gây thanh lý."],"example":"Giả sử bạn gửi 10 ETH vào giao thức liquid staking và nhận khoảng 10 stETH. Với thưởng giả định 3% mỗi năm, sau một năm bạn có khoảng 10,3 stETH. Trong một đợt bán tháo, stETH giao dịch ở 0,97 ETH trên DEX. Nếu bạn phải bán gấp lúc đó, 10,3 stETH chỉ đổi được khoảng 9,99 ETH, gần như mất trọn phần thưởng của năm.","mistakes":["Coi LST luôn bằng đúng 1 coin gốc trong mọi điều kiện thị trường.","Vay đòn bẩy cao bằng LST làm thế chấp mà không tính rủi ro mất neo.","Không phân biệt token stake thanh khoản tự tăng số dư với token tăng theo tỷ giá."],"faq":[{"q":"stETH có phải là ETH không?","a":"Không hẳn. stETH là token đại diện cho ETH đang stake qua Lido, thường giao dịch sát giá ETH nhưng có thể lệch khi thị trường căng thẳng."},{"q":"Staking thanh khoản khác staking trên sàn thế nào?","a":"Staking thanh khoản thường chạy bằng hợp đồng on-chain và trả về token dùng được trong DeFi. Staking trên sàn do sàn giữ coin, đôi khi cũng phát token đại diện nhưng phạm vi sử dụng tùy sàn."}],"title":"Liquid staking là gì? Staking thanh khoản và LST","description":"Staking thanh khoản là gì, token LST như stETH hoạt động thế nào, lợi ích dùng vốn linh hoạt và rủi ro mất neo.","related":[["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["restaking","Restaking (Tái staking)","Restaking là việc dùng lại ETH đã stake hoặc token stake thanh khoản để bảo đảm an ninh thêm cho các dịch vụ khác, nhận thêm phần thưởng nhưng chịu thêm rủi ro bị phạt."],["wrapped-token","Token gói (Wrapped token)","Token gói là token đại diện cho một tài sản khác theo tỷ lệ 1:1, ví dụ WBTC đại diện cho BTC trên Ethereum, giúp tài sản đó dùng được trên blockchain hoặc trong ứng dụng vốn không hỗ trợ nó."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"vi","term":"Restaking (Tái staking)","aka":["restaking","tái staking","LRT"],"short":"Restaking là việc dùng lại ETH đã stake hoặc token stake thanh khoản để bảo đảm an ninh thêm cho các dịch vụ khác, nhận thêm phần thưởng nhưng chịu thêm rủi ro bị phạt.","body":[["Ý tưởng được EigenLayer đưa ra trên ",["Ethereum","ethereum"],": ",["validator","validator"]," hoặc người giữ ",["LST","liquid-staking"]," đồng ý để tài sản đã stake bảo vệ thêm các dịch vụ như mạng ",["oracle","oracle"],", lớp dữ liệu hay ",["cầu nối","cross-chain-bridge"],". Nếu operator làm sai với dịch vụ đó, tài sản có thể bị slashing. Đổi lại, người restake nhận thêm thưởng ngoài ",["staking","staking"]," gốc."],"Các giao thức restaking thanh khoản phát hành token LRT, đại diện cho vị thế restake, có thể dùng tiếp trong DeFi. Nhiều chương trình còn trả điểm thưởng hướng tới airdrop.","Mỗi lớp thêm vào là một lớp rủi ro chồng lên: rủi ro staking gốc, rủi ro hợp đồng restaking, rủi ro slashing từ dịch vụ thêm, và rủi ro LRT mất neo hoặc khó rút. Lợi suất cao hơn không miễn phí."],"example":"Giả sử bạn restake 20 stETH qua một giao thức LRT. Staking gốc mang lại khoảng 3% mỗi năm, phần thêm từ restaking giả định 1,5%, tổng khoảng 4,5%, tức 0,9 ETH. Nếu operator bạn ủy quyền bị phạt 5%, bạn mất 1 ETH, nhiều hơn toàn bộ thu nhập của năm. Nếu LRT giao dịch thấp hơn 2% khi bạn cần bán, khoản lỗ thêm khoảng 0,4 ETH.","mistakes":["Restake toàn bộ ETH chỉ vì muốn tích điểm airdrop.","Không đọc điều kiện slashing và thời gian rút của giao thức restaking.","Dùng LRT làm thế chấp vay đòn bẩy rồi lặp nhiều vòng."],"faq":[{"q":"Restaking khác staking thế nào?","a":"Staking bảo vệ một blockchain. Restaking dùng lại cùng tài sản đó để bảo vệ thêm dịch vụ khác, nên thưởng và rủi ro đều tăng."},{"q":"LRT là gì?","a":"LRT là token restaking thanh khoản, đại diện cho vị thế restake của bạn và có thể giao dịch hoặc dùng trong DeFi."}],"title":"Restaking là gì? Tái staking ETH và token LRT","description":"Restaking là gì, cách EigenLayer và token LRT hoạt động, lợi suất thêm đến từ đâu và các lớp rủi ro chồng lên nhau.","related":[["liquid-staking","Staking thanh khoản (Liquid staking)","Staking thanh khoản là cách stake coin qua một giao thức và nhận lại token đại diện như stETH, có thể giao dịch hoặc dùng trong DeFi trong khi coin gốc vẫn đang được stake."],["staking","Staking","Staking là việc khóa coin của một blockchain proof-of-stake để giúp xác thực giao dịch và bảo vệ mạng lưới, đổi lại nhận phần thưởng bằng chính coin đó."],["validator","Validator (trình xác thực)","Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"vi","term":"Cho vay DeFi (DeFi lending)","aka":["DeFi lending","vay thế chấp crypto","lending"],"short":"Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng.","body":["Người gửi bỏ tài sản vào pool cho vay và nhận lãi từ người vay. Người vay phải thế chấp vượt mức: muốn vay 1.000 USD thì phải gửi tài sản trị giá nhiều hơn 1.000 USD. Lãi suất thả nổi theo mức sử dụng của pool, càng nhiều người vay thì lãi càng cao.",["Mỗi tài sản có ngưỡng ",["thanh lý","liquidation"],". Giao thức theo dõi tỷ lệ an toàn (health factor) dựa trên giá từ ",["oracle","oracle"],". Khi giá thế chấp giảm làm chỉ số này xuống dưới 1, bất kỳ ai cũng có thể trả một phần nợ của bạn và nhận tài sản thế chấp với giá chiết khấu, đó là thanh lý."],["Rủi ro gồm thanh lý khi thị trường giảm nhanh, lỗi hợp đồng, oracle sai giá, và ",["stablecoin","stablecoin"]," bạn vay hoặc gửi bị ",["mất neo","depeg"],". Thông số như ngưỡng thanh lý và phạt thanh lý khác nhau theo giao thức và tài sản."]],"example":["Giả sử bạn gửi 10 ",["ETH","ethereum"]," khi giá 2.500 USD, tức 25.000 USD, với ngưỡng thanh lý 80%. Bạn vay 12.000 ",["USDC","usdc"],". Health factor bằng 25.000 nhân 0,8 chia 12.000, khoảng 1,67. Thanh lý xảy ra khi 10 nhân giá ETH nhân 0,8 bằng 12.000, tức ETH khoảng 1.500 USD. Giá giảm 40% là bạn bị thanh lý, chưa tính lãi vay cộng dồn."],"mistakes":["Vay gần sát mức tối đa cho phép, khiến chỉ một đợt giảm nhỏ cũng gây thanh lý.","Không theo dõi lãi vay thả nổi làm nợ tăng dần theo thời gian.","Chỉ đặt cảnh báo giá trên sàn mà không theo dõi health factor trên giao thức."],"faq":[{"q":"Health factor là gì?","a":"Đó là chỉ số so sánh giá trị thế chấp đã điều chỉnh theo ngưỡng thanh lý với khoản nợ. Dưới 1 là vị thế có thể bị thanh lý."},{"q":"Vì sao phải thế chấp nhiều hơn số tiền vay?","a":"Vì giao thức không biết danh tính người vay, nên dùng tài sản thế chấp dư ra làm vùng đệm trước biến động giá."}],"title":"Cho vay DeFi là gì? Thế chấp, lãi và thanh lý","description":"Cho vay DeFi là gì, cách gửi lãi và vay thế chấp trên Aave, health factor, ngưỡng thanh lý và ví dụ tính giá thanh lý.","related":[["defi","DeFi (Tài chính phi tập trung)","DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."],["oracle","Oracle (Nguồn dữ liệu blockchain)","Oracle là dịch vụ đưa dữ liệu bên ngoài như giá tài sản, kết quả sự kiện hay số ngẫu nhiên vào blockchain để hợp đồng thông minh sử dụng."],["crypto-backed-stablecoin","Stablecoin thế chấp bằng crypto","Stablecoin thế chấp bằng crypto là stablecoin được đúc ra khi người dùng khóa tài sản crypto như ETH vào hợp đồng thông minh với giá trị lớn hơn số stablecoin nhận được."],["flash-loan","Flash loan (Vay nhanh)","Flash loan là khoản vay không cần thế chấp trong DeFi, với điều kiện vay và trả cả gốc lẫn phí trong cùng một giao dịch; nếu không trả đủ, toàn bộ giao dịch bị hủy."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"vi","term":"CBDC (tiền kỹ thuật số của ngân hàng trung ương)","aka":["CBDC","tiền số ngân hàng trung ương","tiền pháp định kỹ thuật số"],"short":"CBDC là dạng tiền pháp định kỹ thuật số do chính ngân hàng trung ương phát hành và bảo đảm, có giá trị ngang tiền mặt của quốc gia đó.","body":["Tiền trong tài khoản ngân hàng hiện nay là khoản nợ của ngân hàng thương mại. CBDC thì khác: nó là khoản nợ trực tiếp của ngân hàng trung ương, giống tờ tiền giấy nhưng ở dạng số. Ví dụ đã triển khai hoặc thử nghiệm có e-CNY của Trung Quốc, eNaira của Nigeria và dự án euro số ở EU.",["CBDC không phải là crypto. Nó không có nguồn cung giới hạn, không phi tập trung, và cơ quan phát hành có thể kiểm soát, giám sát giao dịch. Nhiều CBDC thậm chí không chạy trên ",["blockchain","blockchain"]," công khai."],["Với người dùng crypto, điểm cần chú ý là CBDC có thể trở thành một kênh nạp rút tiền pháp định mới, đồng thời cạnh tranh với ",["stablecoin","stablecoin"]," trong thanh toán. Mức độ riêng tư, giới hạn số dư và cách triển khai khác nhau rất nhiều giữa các quốc gia."]],"example":["Giả sử một quốc gia ra mắt CBDC và cho mỗi người giữ tối đa 3.000 đơn vị trong ví. Bạn nhận lương 10.000 đơn vị, hệ thống tự chuyển 7.000 phần dư sang tài khoản ngân hàng liên kết. Khi đi chợ, bạn trả 200 đơn vị bằng mã QR, giao dịch được ghi nhận ngay và không cần qua ngân hàng thương mại. So với việc trả bằng ",["USDT","usdt"],", bạn không chịu rủi ro lệch giá, nhưng mọi giao dịch đều có thể bị cơ quan phát hành theo dõi."],"mistakes":["Gọi CBDC là một loại crypto hay stablecoin, trong khi bản chất của nó là tiền pháp định do nhà nước phát hành.","Cho rằng CBDC nào cũng chạy trên blockchain và minh bạch như Bitcoin.","Nghĩ rằng CBDC ra đời đồng nghĩa với việc crypto bị cấm."],"faq":[{"q":"CBDC khác stablecoin thế nào?","a":"Stablecoin như USDT hay USDC do công ty tư nhân phát hành và được bảo chứng bằng tài sản dự trữ. CBDC do ngân hàng trung ương phát hành, là tiền pháp định chính thức."},{"q":"Việt Nam có CBDC chưa?","a":"Một số ngân hàng trung ương trong khu vực đang nghiên cứu hoặc thử nghiệm, nhưng tiến độ mỗi nước khác nhau. Hãy theo dõi thông báo chính thức của Ngân hàng Nhà nước để có thông tin chính xác."}],"title":"CBDC là gì? Tiền kỹ thuật số ngân hàng trung ương","description":"CBDC là tiền pháp định dạng số do ngân hàng trung ương phát hành. So sánh CBDC với crypto, stablecoin và ví dụ dễ hiểu.","related":[["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["fiat-on-ramp","Cổng nạp tiền pháp định (fiat on-ramp)","Cổng nạp tiền pháp định là dịch vụ cho phép bạn đổi tiền như VND hay USD thành crypto, qua chuyển khoản ngân hàng, thẻ, ví điện tử hoặc giao dịch P2P."],["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"vi","term":"Node (nút mạng blockchain)","aka":["node","nút mạng","full node"],"short":"Node là máy tính chạy phần mềm của một blockchain, lưu dữ liệu chuỗi, kiểm tra giao dịch và khối theo quy tắc của mạng, rồi chia sẻ chúng với các node khác.","body":[["Mạng ",["blockchain","blockchain"]," không có máy chủ trung tâm. Thay vào đó, hàng nghìn node trên khắp thế giới cùng giữ một bản sao sổ cái và tự kiểm tra từng khối mới. Nếu một khối vi phạm quy tắc, ví dụ tạo thêm ",["BTC","bitcoin"]," vượt mức cho phép, các node trung thực sẽ từ chối nó."],["Có nhiều loại node. Full node lưu và xác minh toàn bộ chuỗi. Light node chỉ tải phần dữ liệu cần thiết và dựa vào full node khác. Archive node lưu cả lịch sử trạng thái đầy đủ, thường phục vụ ",["explorer","block-explorer"]," và nhà phân tích. ",["Validator","validator"]," trong mạng ",["proof of stake","proof-of-stake"]," là node có stake và tham gia tạo khối."],"Với người dùng thông thường, ví thường kết nối qua node của nhà cung cấp dịch vụ RPC. Chạy node riêng giúp bạn tự xác minh giao dịch mà không phải tin bên thứ ba, đổi lại cần dung lượng ổ cứng, băng thông và thời gian đồng bộ."],"example":["Giả sử bạn muốn chạy full node Bitcoin tại nhà. Bạn cần một ổ SSD trống vài trăm GB, kết nối internet ổn định và vài ngày để tải và xác minh toàn bộ lịch sử. Sau khi đồng bộ, ví của bạn có thể kiểm tra số dư và giao dịch trực tiếp qua node của chính mình. Nếu ai đó gửi bạn 0,05 BTC, chính node của bạn ",["xác nhận","block-confirmations"]," giao dịch hợp lệ, thay vì tin vào máy chủ của một công ty ví."],"mistakes":["Nghĩ rằng chạy node Bitcoin là đang đào coin và sẽ nhận phần thưởng.","Dùng endpoint RPC lạ do người khác gửi, có thể hiển thị dữ liệu sai lệch.","Đánh giá thấp dung lượng ổ cứng và băng thông cần cho một full node."],"faq":[{"q":"Chạy node có được trả tiền không?","a":"Full node Bitcoin thông thường không nhận thưởng. Validator trong mạng proof of stake thì nhận thưởng vì họ khóa stake và tham gia tạo khối."},{"q":"Node và validator khác nhau thế nào?","a":"Mọi validator đều là node, nhưng không phải node nào cũng là validator. Node có thể chỉ xác minh và chuyển tiếp dữ liệu mà không tham gia tạo khối."}],"title":"Node là gì? Vai trò của nút mạng trong blockchain","description":"Node là máy tính giữ sổ cái và xác minh giao dịch. Phân biệt full node, light node, archive node và validator.","related":[["blockchain","Blockchain (chuỗi khối)","Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau."],["validator","Validator (trình xác thực)","Validator (trình xác thực) là node trên blockchain bằng chứng cổ phần, khóa coin làm tài sản đảm bảo để đề xuất, kiểm tra và bỏ phiếu cho các khối mới, đổi lại nhận phần thưởng."],["mining","Đào coin (Crypto mining)","Đào coin (crypto mining) là quá trình dùng máy tính chuyên dụng giải bài toán mật mã để xác nhận giao dịch, thêm khối mới vào blockchain bằng chứng công việc và nhận coin mới làm phần thưởng."],["mempool","Mempool (vùng chờ giao dịch)","Mempool là nơi các giao dịch đã được phát lên mạng nhưng chưa được đưa vào khối nằm chờ, trước khi thợ đào hoặc validator chọn để xác nhận."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"vi","term":"AML (phòng chống rửa tiền)","aka":["AML","chống rửa tiền","anti-money laundering"],"short":"AML là tập hợp quy định và quy trình mà sàn giao dịch và tổ chức tài chính áp dụng để phát hiện, ngăn chặn và báo cáo hoạt động rửa tiền hoặc tài trợ khủng bố.","body":[[["KYC","kyc"]," là bước đầu của AML, nhưng AML rộng hơn. Sau khi bạn mở tài khoản, sàn tiếp tục theo dõi giao dịch: nguồn tiền nạp vào, ví nhận khi rút ra, tần suất và quy mô giao dịch. Các công cụ phân tích ",["blockchain","blockchain"]," giúp sàn đánh giá rủi ro của từng ",["địa chỉ ví","wallet-address"],"."],"Nếu coin bạn nạp có liên quan đến ví bị đánh dấu, như ví của vụ hack, sàn đen hay dịch vụ trộn coin, sàn có thể tạm giữ, yêu cầu giải trình nguồn tiền hoặc báo cáo cơ quan chức năng. Mức độ nghiêm ngặt khác nhau tùy luật từng nước và chính sách từng sàn.",["Với người ",["giao dịch P2P","p2p-trading"],", AML đặc biệt quan trọng: nhận tiền từ tài khoản ngân hàng của bên thứ ba có thể khiến tài khoản ngân hàng của bạn bị phong tỏa nếu tiền đó liên quan đến lừa đảo."]],"example":["Giả sử bạn bán 2.000 ",["USDT","usdt"]," qua P2P và nhận khoảng 50 triệu đồng. Người mua chuyển tiền từ tài khoản mang tên khác với tên trên sàn. Bạn vẫn thả coin. Vài ngày sau, ngân hàng phong tỏa tài khoản của bạn vì khoản 50 triệu đó là tiền của nạn nhân lừa đảo. Nếu tuân thủ đúng quy trình, chỉ nhận tiền từ tài khoản trùng tên đã xác minh, bạn đã tránh được rủi ro này."],"mistakes":["Nhận tiền từ tài khoản ngân hàng không trùng tên người mua trong giao dịch P2P.","Nạp coin vừa đi qua dịch vụ trộn lên sàn tập trung rồi bất ngờ khi bị tạm giữ.","Bỏ qua yêu cầu giải trình nguồn tiền của sàn, khiến tài khoản bị hạn chế lâu hơn."],"faq":[{"q":"AML và KYC khác nhau thế nào?","a":"KYC là xác minh bạn là ai. AML là toàn bộ hệ thống giám sát giao dịch để phát hiện rửa tiền, trong đó KYC chỉ là một phần."},{"q":"Sàn yêu cầu chứng minh nguồn tiền thì cần gì?","a":"Thường là sao kê ngân hàng, hợp đồng lao động, hóa đơn mua bán hoặc lịch sử giao dịch trên sàn khác. Hãy cung cấp qua kênh chính thức và giữ thông tin nhất quán."}],"title":"AML là gì? Phòng chống rửa tiền trên sàn crypto","description":"AML là quy trình chống rửa tiền của sàn crypto. Tìm hiểu cách sàn giám sát giao dịch, vì sao tiền bị giữ và cách phòng tránh.","related":[["kyc","KYC (xác minh danh tính khách hàng)","KYC là quy trình sàn giao dịch hoặc tổ chức tài chính xác minh danh tính người dùng bằng giấy tờ tùy thân, ảnh khuôn mặt và đôi khi là địa chỉ cư trú."],["travel-rule","Travel rule (quy tắc chuyển tiền)","Travel rule là quy định yêu cầu các nhà cung cấp dịch vụ tài sản ảo gửi kèm thông tin người gửi và người nhận khi chuyển crypto giữa các tổ chức với nhau."],["vasp","VASP (nhà cung cấp dịch vụ tài sản ảo)","VASP là tổ chức cung cấp dịch vụ liên quan đến tài sản ảo cho người khác, như sàn giao dịch, dịch vụ lưu ký hoặc chuyển đổi crypto, và chịu các nghĩa vụ quản lý như KYC, AML."],["p2p-trading","Giao dịch P2P (C2C)","Giao dịch P2P là hình thức mua bán crypto trực tiếp giữa hai người dùng trên một nền tảng, trong đó sàn giữ coin của người bán làm bảo đảm cho tới khi người mua thanh toán xong."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC thực hiện như thế nào và ai mới là người nhận giấy tờ của bạn?"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"vi","term":"Vàng token hóa (tokenized gold)","aka":["tokenized gold","vàng số","PAXG","XAUT"],"short":"Vàng token hóa là token trên blockchain đại diện cho quyền sở hữu một lượng vàng vật chất cụ thể được lưu giữ trong kho, phổ biến nhất là PAXG và XAUT.","body":["PAX Gold do Paxos phát hành và Tether Gold do Tether phát hành, mỗi token tương ứng với một ounce troy vàng, khoảng 31,1 gram, được lưu tại kho. Giá token vì vậy bám theo giá vàng thế giới chứ không theo thị trường crypto.",["Ưu điểm là có thể mua lẻ một phần nhỏ của ounce, giao dịch 24/7 trên sàn crypto, chuyển nhanh giữa các ví và dùng trong ",["DeFi","defi"],". Một số nhà phát hành cho phép đổi token lấy vàng vật chất hoặc tiền mặt, nhưng thường có số lượng tối thiểu, phí và yêu cầu ",["KYC","kyc"],"."],["Rủi ro chính là nhà phát hành và kho lưu giữ: bạn tin rằng vàng thật đang có đủ. Hãy xem báo cáo kiểm toán dự trữ. Ngoài ra, giá trên sàn crypto có thể lệch nhẹ so với giá vàng giao ngay khi ",["thanh khoản","liquidity"]," thấp."]],"example":["Giả sử giá vàng thế giới là 2.400 USD mỗi ounce và bạn muốn giữ khoảng 600 USD vàng. Bạn mua 0,25 PAXG với khoảng 600 ",["USDT","usdt"],". Nếu vàng tăng 5% lên 2.520 USD, phần của bạn trị giá khoảng 630 USD. Nếu thị trường crypto giảm mạnh cùng lúc, PAXG vẫn bám theo giá vàng, nhưng thanh khoản trên sàn có thể mỏng, nên bán ngay với số lượng lớn có thể bị ",["trượt giá","slippage"],"."],"mistakes":["Nghĩ vàng token hóa sẽ biến động như crypto, trong khi giá của nó bám theo giá vàng.","Bỏ qua điều kiện và số lượng tối thiểu nếu muốn đổi ra vàng vật chất.","Không kiểm tra báo cáo dự trữ của nhà phát hành."],"faq":[{"q":"PAXG và XAUT khác nhau thế nào?","a":"Cả hai đều tương ứng một ounce troy vàng. Khác biệt nằm ở nhà phát hành, nơi lưu kho, cách đổi lấy vàng và blockchain mà token chạy trên đó."},{"q":"Có đổi vàng token hóa lấy vàng thật được không?","a":"Một số nhà phát hành cho phép, thường cần số lượng tối thiểu lớn, KYC và chịu phí vận chuyển. Điều kiện cụ thể nằm trên trang chính thức của nhà phát hành."}],"title":"Vàng token hóa là gì? PAXG và XAUT hoạt động thế nào","description":"Vàng token hóa đại diện cho vàng vật chất trên blockchain. Tìm hiểu PAXG, XAUT, cách bảo chứng, đổi vàng thật và các rủi ro.","related":[["real-world-assets","Tài sản thực (RWA)","Tài sản thực, hay RWA, là các tài sản ngoài blockchain như trái phiếu, vàng, bất động sản hay khoản vay được token hóa để có thể nắm giữ và giao dịch trên chuỗi."],["stablecoin","Stablecoin (Đồng tiền ổn định)","Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC."],["custodial-wallet","Ví lưu ký (Custodial wallet)","Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase."],["tokenized-stocks","Cổ phiếu token hóa (tokenized stocks)","Cổ phiếu token hóa là token đại diện cho giá trị của một cổ phiếu niêm yết như Apple hay Tesla, thường được bảo chứng bởi cổ phiếu thật do một đơn vị lưu ký nắm giữ."]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
